import { MOCK_ATHLETE_PROFILE_METADATA } from "./mock-athlete-profiles.js";

const sampleMedia = (name, sportId, overrides = {}) => Object.freeze({
  illustrationUrl: overrides.illustrationUrl || "",
  illustrationVersion: overrides.illustrationVersion || "1.0",
  artStyleId: overrides.artStyleId || "edgeboard-geometric-placeholder",
  artistName: overrides.artistName || "EdgeBoard sample design",
  headshotUrl: overrides.headshotUrl || "",
  silhouetteUrl: overrides.silhouetteUrl
    || (sportId === "motorsport" ? "assets/motorsport-silhouette.svg" : "assets/athlete-silhouette.svg"),
  fallbackInitials: name.split(/\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase(),
  altText: `${name} sample profile placeholder`,
  attribution: overrides.attribution || "Original EdgeBoard abstract placeholder",
  rightsStatus: overrides.rightsStatus || "original-placeholder",
  approvedForCommercialUse: overrides.approvedForCommercialUse ?? true,
  source: overrides.source || "EdgeBoard sample assets",
  updatedAt: "2026-07-28T15:20:00.000Z",
});

function athlete(id, name, sportId, leagueId, teamId, aliases = [], options = {}) {
  return Object.freeze({
    id,
    name,
    entityType: options.entityType || "player",
    sportId,
    leagueId,
    teamId,
    aliases: Object.freeze(aliases),
    providerIds: Object.freeze(options.providerIds || { edgeboardMock: id }),
    active: options.active !== false,
    position: options.position || "",
    weightClass: options.weightClass || "",
    stance: options.stance || "",
    profile: MOCK_ATHLETE_PROFILE_METADATA[id] || Object.freeze({
      sample: true,
      shortName: name,
      teamName: teamId,
      organization: teamId,
      role: options.position || "",
      status: options.active === false ? "Inactive" : "Active",
      availabilityStatus: options.active === false ? "Inactive" : "Available",
      seasonLabel: "Illustrative sample",
      nextEvent: null,
      matchup: null,
    }),
    media: sampleMedia(name, sportId, options.media || {}),
  });
}

function team(id, name, sportId, leagueId, aliases = []) {
  return Object.freeze({
    id,
    name,
    entityType: "team",
    sportId,
    leagueId,
    teamId: id,
    aliases: Object.freeze(aliases),
    providerIds: Object.freeze({ edgeboardMock: id }),
    active: true,
    position: "",
    media: sampleMedia(name, sportId),
  });
}

